include <robotics.scad>
// Hokuyo UST-10LX base housing. Origin: bottom face centre. Front = -Y, rear (cables) = +Y.
B = [50, 50, 35];     // official
hp = 40;              // bottom hole square, official
m3_tap = 2.5; m3_d = 6;     // 2-M3 depth 6
pin_d = 3;  pin_dp = 2.8;   // 2-Ø3 depth 2.8
m4_tap = 3.3; m4_dp = 6; m4_dx = 42; m4_z = 17.5; // 2-M4 depth 6 rear
$fn = 40;
diff() {
  cuboid(B, rounding = 1, anchor = BOT);   // radius undimensioned: minimal
  // bottom M3 (one diagonal)
  for (p = [[ hp/2, -hp/2], [-hp/2, hp/2]])
    tag("remove") translate([p.x, p.y, -0.01]) cyl(d = m3_tap, h = m3_d + 0.01, anchor = BOT);
  // bottom Ø3 locating holes (other diagonal)
  for (p = [[ hp/2, hp/2], [-hp/2, -hp/2]])
    tag("remove") translate([p.x, p.y, -0.01]) cyl(d = pin_d, h = pin_dp + 0.01, anchor = BOT);
  // rear M4
  for (xs = [-1, 1])
    tag("remove") translate([xs*m4_dx/2, B.y/2 + 0.01, m4_z]) ycyl(d = m4_tap, h = m4_dp + 0.01, anchor = BACK);
}

include <robotics.scad>
// Optical window band. Origin: its bottom face centre (sits on base top, z = 35).
W = 42;      // plan size, scaled from drawing - NOT dimensioned
H = 28.7;    // official
cuboid([W, W, H], rounding = 1, edges = "Z", anchor = BOT);

include <robotics.scad>
// Top cap. Origin: bottom face centre at z = 63.7.
W = 42;            // NOT dimensioned
H = 70 - 63.7;     // 6.3, from official numbers
cuboid([W, W, H], rounding = 1, anchor = BOT);

include <robotics.scad>
// Rear cable plate. Origin: rear body face (y = 25), at z = 0, x = 0.
w = 24; z0 = 4; h = 13;     // official
t = 1;                      // plate thickness, undimensioned
proud = 2.8;                // official: cable exit behind the body
g_dx = 11.5; g_z = 10.5;    // official
$fn = 40;
translate([0, 0, z0]) cuboid([w, t, h], rounding = 1, edges = "Y", anchor = BOT + FRONT);
translate([-g_dx/2, t, g_z]) ycyl(d = 6, h = proud - t, anchor = FRONT);  // Ethernet gland
translate([ g_dx/2, t, g_z]) ycyl(d = 5, h = proud - t, anchor = FRONT);  // power/IO gland
